Strategies = {(2, 0.25, 0.1, 0): state_action_strategy_2_025_010_000,
              (2, 0.25, 0.1, 130): state_action_strategy_2_025_010_130}


def decide_action(c1, c2, state, all_in, bb, sb, jp):
    strategy = Strategies[(all_in, bb, sb, jp)]
    M = max(c1.number.value, c2.number.value)
    m = min(c1.number.value, c2.number.value)
    suit = int(c1.suit == c2.suit)

    if M == m and suit:
        print("-E- impossible cards, assuming unsuit")
        suit = 0

    hand_idx = (M-2) ** 2 + 2 * (m-2) + suit
    act = strategy[hand_idx][state.value]
    if act > random.uniform(0, 1) * 100:
        return Action.AllIn
    return Action.Fold

